-- ============================================
-- LUMA — Thème 5 : LONG 1/3 x4 — Un séjour bref à l'hôpital à l'étranger
-- ============================================


update scenarios set content = '{"characters": {"taxi_driver": "le chauffeur", "receptionist": "la réceptionniste", "nurse": "l''infirmière", "doctor": "le médecin", "stranger": "un passant"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You slipped on wet stairs while sightseeing and can''t put weight on your ankle.)", "text_fr": "(Vous avez glissé sur des marches mouillées en visitant, et vous ne pouvez pas mettre de poids sur votre cheville.)", "choices": [{"text": "(Call a taxi to get to the nearest hospital.)", "text_fr": "(Appelle un taxi pour aller à l''hôpital le plus proche.)", "next": "n2"}, {"text": "(Ask nearby people if there''s a hospital within walking distance.)", "text_fr": "(Demande aux gens à proximité s''il y a un hôpital à distance de marche.)", "next": "n2b"}]}, "n2": {"speaker": "taxi_driver", "text": "Hospital, got it — you okay back there? That looks painful.", "text_fr": "Hôpital, compris — ça va derrière ? Ça a l''air douloureux.", "choices": [{"text": "It really hurts, but I''ll manage. Thank you for the quick ride.", "text_fr": "Ça fait vraiment mal, mais je vais gérer. Merci pour le trajet rapide.", "next": "n3"}]}, "n2b": {"speaker": "stranger", "text": "There''s one about ten minutes away, but let me just call you a taxi instead.", "text_fr": "Il y en a un à environ dix minutes, mais laissez-moi plutôt vous appeler un taxi.", "choices": [{"text": "That''s very kind, thank you so much.", "text_fr": "C''est très gentil, merci beaucoup.", "next": "n3"}]}, "n3": {"speaker": "receptionist", "text": "Welcome, what happened?", "text_fr": "Bienvenue, que s''est-il passé ?", "choices": [{"text": "I fell on some stairs and I think I hurt my ankle badly.", "text_fr": "Je suis tombé dans des escaliers et je pense m''être fait mal à la cheville.", "next": "n4"}]}, "n4": {"speaker": "receptionist", "text": "I''ll need your passport and travel insurance information, please.", "text_fr": "J''aurai besoin de votre passeport et de vos informations d''assurance voyage, s''il vous plaît.", "choices": [{"text": "Here you go — I have my insurance card in my wallet.", "text_fr": "Voici — j''ai ma carte d''assurance dans mon portefeuille.", "next": "n5"}, {"text": "Here''s my passport. My insurance is through an app, let me pull it up.", "text_fr": "Voici mon passeport. Mon assurance est via une appli, laissez-moi la trouver.", "next": "n5"}]}, "n5": {"speaker": "receptionist", "text": "Perfect, please have a seat, a nurse will call you shortly.", "text_fr": "Parfait, asseyez-vous s''il vous plaît, une infirmière va vous appeler bientôt.", "choices": [{"text": "Thank you, do you know roughly how long the wait might be?", "text_fr": "Merci, vous savez à peu près combien de temps l''attente pourrait être ?", "next": "n6"}, {"text": "Thank you, I''ll wait right here.", "text_fr": "Merci, je vais attendre juste ici.", "next": "n6"}]}, "n6": {"speaker": "nurse", "text": "(Calls your name) Let''s take a look at that ankle.", "text_fr": "(Appelle votre nom) Regardons cette cheville.", "choices": [{"text": "It really hurts when I try to put any weight on it.", "text_fr": "Ça fait vraiment mal quand j''essaie de mettre du poids dessus.", "next": "n7"}]}, "n7": {"speaker": "nurse", "text": "We''ll need an X-ray to check for a fracture. Follow me, please.", "text_fr": "On va avoir besoin d''une radio pour vérifier une fracture. Suivez-moi, s''il vous plaît.", "choices": [{"text": "(Follow the nurse for the X-ray.)", "text_fr": "(Suis l''infirmière pour la radio.)", "next": "n8"}]}, "n8": {"speaker": "doctor", "text": "Good news — it''s not broken, just a significant sprain.", "text_fr": "Bonne nouvelle — ce n''est pas cassé, juste une entorse importante.", "choices": [{"text": "That''s a relief. What do I need to do to recover?", "text_fr": "Ça soulage. Qu''est-ce que je dois faire pour récupérer ?", "next": "n9"}, {"text": "Thank goodness. Will I still be able to travel?", "text_fr": "Dieu merci. Je pourrai quand même voyager ?", "next": "n9b"}]}, "n9": {"speaker": "doctor", "text": "Rest, ice, compression, and elevation for the next week. I''ll give you a brace too.", "text_fr": "Repos, glace, compression, et élévation pendant la semaine à venir. Je vous donne aussi une attelle.", "choices": [{"text": "Understood, thank you for explaining everything clearly.", "text_fr": "Compris, merci d''avoir tout expliqué clairement.", "next": "n10"}]}, "n9b": {"speaker": "doctor", "text": "You should be fine with the brace, but avoid long walks for a few days.", "text_fr": "Vous devriez aller bien avec l''attelle, mais évitez les longues marches pendant quelques jours.", "choices": [{"text": "That''s manageable, thank you doctor.", "text_fr": "C''est gérable, merci docteur.", "next": "n10"}]}, "n10": {"speaker": "receptionist", "text": "Here''s your paperwork for insurance reimbursement, and your prescription.", "text_fr": "Voici vos documents pour le remboursement de l''assurance, et votre ordonnance.", "choices": [{"text": "Thank you, this has been much easier than I expected.", "text_fr": "Merci, c''était bien plus facile que ce à quoi je m''attendais.", "next": "n11"}, {"text": "Thank you — will my insurance cover this fully?", "text_fr": "Merci — mon assurance couvrira ça entièrement ?", "next": "n11b"}]}, "n11": {"speaker": "receptionist", "text": "Glad to hear it! Just submit these forms to your insurance when you''re home.", "text_fr": "Ravie de l''entendre ! Soumettez juste ces formulaires à votre assurance en rentrant.", "choices": [{"text": "Will do, thank you for all your help today.", "text_fr": "C''est noté, merci pour votre aide aujourd''hui.", "next": "end_smooth"}]}, "n11b": {"speaker": "receptionist", "text": "Based on your policy, it looks like most costs will be covered.", "text_fr": "D''après votre police, il semble que la plupart des frais seront couverts.", "choices": [{"text": "That''s a relief, thank you for checking.", "text_fr": "Ça soulage, merci d''avoir vérifié.", "next": "end_smooth"}]}, "end_smooth": {"speaker": "you_thought", "text": "(Despite the scare, the whole hospital experience abroad went surprisingly smoothly.)", "text_fr": "(Malgré la frayeur, toute l''expérience hospitalière à l''étranger s''est déroulée étonnamment bien.)", "end": true, "ending_label": "Hospitalisation à l''étranger bien gérée 🏥✈️✅"}}}'::jsonb, is_playable = true
where title = 'Un séjour bref à l''''hôpital à l''''étranger'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
